# Med Pass — Exam 1 medications (Weeks 1.1–2.3), built only from the Exam 1 lecture files.
# Same fields as Med Pass 4: g generic · b brand · cls · grp · u overlap tags · use · f facts (true only for this drug
# among drugs it doesn't share a tag with) · tip · warn (Learn's big warning)
def D(g,b,cls,grp,u,use,f,tip,warn,cno=None):
    d={"g":g,"b":b,"cls":cls,"grp":grp,"u":u,"use":use,"f":f,"tip":tip,"warn":warn}
    if cno: d["cno"]=cno
    return d

